# AI Office v2.5 Part L Release Dashboard Docs Git Sync Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
if(-not(Test-Path $Repository)){throw "AI Office repository not found."}
Set-Location $Repository
$Timestamp=Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory=Join-Path $Repository ("workspace\installer-backups\v2.5-part-l-"+$Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force|Out-Null
function Write-EmbeddedFile{
 param([string]$RelativePath,[string]$Base64Content)
 $Dest=Join-Path $Repository $RelativePath
 $Parent=Split-Path -Parent $Dest
 if($Parent){New-Item -ItemType Directory -Path $Parent -Force|Out-Null}
 if(Test-Path $Dest){
  $Backup=Join-Path $BackupDirectory $RelativePath
  New-Item -ItemType Directory -Path (Split-Path -Parent $Backup) -Force|Out-Null
  Copy-Item $Dest $Backup -Force
 }
 [IO.File]::WriteAllBytes($Dest,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\release-manifest.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5-Release-Notes.md" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Update-AIOfficeIntelligenceDashboardData.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Sync-AIOfficeV25ProjectDocs.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Publish-AIOfficeV25Release.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeV25ReleaseReadiness.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Get-AIOfficeV25GitReleaseCommands.ps1" -Base64Content ""
$Scripts=@(
"E:\AI\AI-Office\scripts\intelligence\Update-AIOfficeIntelligenceDashboardData.ps1",
"E:\AI\AI-Office\scripts\intelligence\Sync-AIOfficeV25ProjectDocs.ps1",
"E:\AI\AI-Office\scripts\intelligence\Publish-AIOfficeV25Release.ps1",
"E:\AI\AI-Office\scripts\intelligence\Test-AIOfficeV25ReleaseReadiness.ps1",
"E:\AI\AI-Office\scripts\intelligence\Get-AIOfficeV25GitReleaseCommands.ps1")
foreach($Script in $Scripts){$T=$null;$E=$null;[System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$T,[ref]$E)|Out-Null;if($E.Count-gt0){throw ("Syntax error in "+$Script+": "+(($E|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.5 Part L Release, Dashboard, Docs and Git Sync installed successfully." -ForegroundColor Green
Write-Host "Release is not published until Publish-AIOfficeV25Release.ps1 is run." -ForegroundColor Yellow
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan